const fs = require('fs');

const [N, M, S] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

function digitSum(value) {
  let sum = 0;
  while (value > 0) {
    sum += value % 10;
    value = Math.floor(value / 10);
  }
  return sum;
}

for (let i = M; i >= N; i--) {
  if (digitSum(i) === S) {
    console.log(i);
    process.exit(0);
  }
}

console.log(-1);
